&reftitle.description;
arrayarray_change_key_case arrayarray intcaseCASE_LOWER
array from का सबै keys लाई lower case वा upper case मा convert गरिएको एउटा array return गर्दछ। Numbered indices लाई जस्ताको तस्तै छोडिन्छ।

  &reftitle.examples;



    array_change_key_case को उदाहरण


<?php
$input_array = array("FirSt" => 1, "SecOnd" => 4);
print_r(array_change_key_case($input_array, CASE_UPPER));
?>


    &example.outputs;


Array
(
    [FIRST] => 1
    [SECOND] => 4
)
